head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 1번을 실행 후 개발자모드(F12)에서 요소검사를 통해 "accessibility_chart_ref1"를 검색한다.
    //1. Execute sample file 1 and search for "accessibility_chart_ref1" through element check in developer mode (F12).
    //Verify 1. <li> Age: 20, rate: 10% </ li>
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_ref1').childNodes[1].innerText == '나이 : 20대, 비율 : 10%'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_ref1').getElementsByTagName ('tbody')[0].childNodes[0].childNodes[0].innerText == '20대'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_ref1').getElementsByTagName ('tbody')[0].childNodes[0].childNodes[1].innerText == '10%'", "true");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_ref1').childNodes[1].tagName == 'LI'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('accessibility_'+$p.id+'chart_ref1').getElementsByTagName ('tbody')[0].childNodes[0].tagName == 'TR'", "true");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.circle = {
        "chart": {},
        "data": [{
            "label": "20대",
            "value": "10%"
        }, {
            "label": "30대",
            "value": "20%"
        }, {
            "label": "40대",
            "value": "50%"
        }, {
            "label": "50대",
            "value": "45%"
        }]
    };
    window.circle_options = {
        "caption": "cart 대제목",
        "subCaption": "Sub 소제목",
        "ayAxisName": "비율",
        "axAxisName": "나이",
        //"ayaxisname": "비율", //웹접근성 y축 값 
        //"axaxisname": "나이", //웹접근성 x축 값
        "formatnumberscale": "0",
        "numberprefix": "",
        "pieslicedepth": "30",
        "startingangle": "125",
        "showLegend": "1"
    };
    chart_ref1.setChartAttribute(circle_options);
    chart_ref1.setJSONData(circle);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
